INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-01-01-finland-peppol-advanced-ordering', '2025-01-01', '2025-01', 'Finland''s Central Government now requires Peppol Advanced Ordering for all invoicing, extending standardisation into the ordering process itself — while domestic B2B e-invoicing remains entirely voluntary, with no mandate date in sight.', '<h3>🇫🇮 Finland mandates Peppol Advanced Ordering for Central Government, while B2B stays voluntary</h3>
<p>Finland''s Central Government has extended its e-invoicing standardisation a step further this year, now requiring Peppol Advanced Ordering across all its invoicing relationships. This builds on a B2G e-invoicing mandate that''s been in force since April 2020, and a requirement since April 2021 that all invoices sent to government agencies be genuinely EN 16931-compliant, not just superficially similar to the standard. Roughly 99% of invoices to Finnish public buyers are already electronic — this latest step pushes standardisation into the ordering process itself, not just the invoice.</p>
<p>Worth being clear about what hasn''t changed: Finland still has no domestic B2B e-invoicing mandate of any kind, and none is currently scheduled. Businesses with turnover above €10,000 have a statutory right under the 2019 eInvoicing Act to demand e-invoices from their suppliers, and B2B adoption is genuinely widespread as a result — but nothing requires a business to issue them. The only firm future date on Finland''s e-invoicing horizon is the EU''s ViDA deadline of 1 July 2030, for intra-EU B2B transactions specifically, and Finland has indicated it plans to implement at that point rather than moving earlier the way several of its EU neighbours are choosing to.</p>
<p><strong>What this means for your team:</strong> if you supply Finnish Central Government specifically, confirm your ordering process — not just your invoicing — is genuinely Peppol Advanced Ordering compatible, since this is a step beyond what most B2G mandates in this tracker require. For everything else in Finland, don''t wait for a domestic B2B mandate that doesn''t currently exist — if your counterparties expect e-invoices contractually, that expectation is the real driver here, not a statutory deadline.</p>', 'https://www.valtiokonttori.fi/en/e-invoicing-fast-and-safe/', 1);
